mapper.select:
select * from( select distinct tt.* from ( select portfolioId,portfolioName,secAcctId,secAcctName,finprodId,finprodMarketId,finprodAbbr, type9, type10, type11, type12, type8, type7, type6, actualPositionAmount, tradePositionAmount, instructionsAmount, pledgeAmount, preReductionAmount, nvl(marketPrice,decode(type8,'F01',100,1))*actualPositionAmount marketValue from ( select portfolioId,portfolioName,secAcctId,secAcctName,finprodId,finprodMarketId,finprodAbbr, type9, type10, type11, type12, type8, type7, type6, case when type8 in ('F01','F04','F11') or (type8 = 'F02' and tradeMarket in ('03','04','09')) then marketPrice else 1 end as marketPrice, case when type8 in (#{finprodType2_F01},#{finprodType2_F10},#{finprodType2_F37}) then (PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06)*100 else (PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06) end as actualPositionAmount,
case when type8 in (#{finprodType2_F01},#{finprodType2_F10},#{finprodType2_F37}) then (PTL_FLOW_AMOUNT01-PTL_FLOW_AMOUNT10 + PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06 - PTL_AMOUNT04 + PTL_AMOUNT08 + andOneDataAmout)*100
else (PTL_FLOW_AMOUNT01 + PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06 - PTL_AMOUNT04 + PTL_AMOUNT08) end as tradePositionAmount, case when type8 in (#{finprodType2_F01},#{finprodType2_F10},#{finprodType2_F37}) then ETR_FLOW_AMOUNTE01*100 else ETR_FLOW_AMOUNTE01 end as instructionsAmount, case when type8 in (#{finprodType2_F01},#{finprodType2_F10},#{finprodType2_F37}) then ETR_FLOW_AMOUNT04*100 else ETR_FLOW_AMOUNT04 end as preReductionAmount, case when type8 in (#{finprodType2_F01},#{finprodType2_F10},#{finprodType2_F37}) then (PTL_AMOUNT04)*100 else (PTL_AMOUNT04) end as pledgeAmount from ( select t.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, nvl(nvl(chl.FINPROD_MARKET_ID, chl1.FINPROD_MARKET_ID), t.SEC_ACCT_ID) secAcctId, nvl(t4.SEC_ACCT_NAME, nvl(chl.FINPROD_ABBR, chl1.FINPROD_ABBR)) secAcctName, t.FINPROD_ID finprodId, nvl(fp.FINPROD_MARKET_ID, t.FINPROD_ID) finprodMarketId, nvl(fp.FINPROD_ABBR, t.FINPROD_ID) finprodAbbr, t5.TYPE_9 type9, t5.TYPE_10 type10, t5.TYPE_11 type11, t5.TYPE_12 type12, t5.TYPE_8 type8, t5.TYPE_7 type7, t5.TYPE_6 type6, mv.marketPrice marketPrice, fp.TRADE_MARKET tradeMarket, nvl(sum(PTL_AMOUNT03),0) as PTL_AMOUNT03, nvl(sum(PTL_AMOUNT04),0) as PTL_AMOUNT04, nvl(sum(PTL_AMOUNT05),0) as PTL_AMOUNT05, nvl(sum(PTL_AMOUNT06),0) as PTL_AMOUNT06, nvl(sum(PTL_AMOUNT08),0) as PTL_AMOUNT08, nvl(sum(PTL_FLOW_AMOUNT01),0) as PTL_FLOW_AMOUNT01, nvl(sum(PTL_FLOW_AMOUNT10),0) as PTL_FLOW_AMOUNT10, nvl(sum(ETR_FLOW_AMOUNTE01),0) as ETR_FLOW_AMOUNTE01, nvl(sum(ETR_FLOW_AMOUNT04),0) as ETR_FLOW_AMOUNT04
, nvl(sum(andOneDataAmout),0) as andOneDataAmout
from ( SELECT t6.portfolio_id, DECODE(t6.sec_acct_id, '999999', NULL, t6.sec_acct_id) sec_acct_id, t6.finprod_id, t6.PTL_AMOUNT03, t6.PTL_AMOUNT04, t6.PTL_AMOUNT05, t6.PTL_AMOUNT06, t6.PTL_AMOUNT08, t7.PTL_FLOW_AMOUNT01,t7.PTL_FLOW_AMOUNT10, t8.ETR_FLOW_AMOUNTE01, t8.ETR_FLOW_AMOUNT04
, t_andOneData.andOneDataAmout
FROM ( select portfolio_id, sec_acct_id, finprod_id, nvl(sum(case when hoding_type = '03' then AMOUNT end),0) PTL_AMOUNT03, nvl(sum(case when hoding_type = '04' then AMOUNT end),0) PTL_AMOUNT04, nvl(sum(case when hoding_type = '05' then AMOUNT end),0) PTL_AMOUNT05, nvl(sum(case when hoding_type = '06' then AMOUNT end),0) PTL_AMOUNT06, nvl(sum(case when hoding_type = '08' then AMOUNT end),0) PTL_AMOUNT08 from PTL_SEC_POSITION
where 1=1
and portfolio_id in (
#{prot,jdbcType=VARCHAR} )
and cdate = to_date(#{cdate},'yyyy-MM-dd')
and finprod_id = #{finprodId,jdbcType=VARCHAR}
#{secHodingType,jdbcType=VARCHAR}
group by portfolio_id, sec_acct_id, finprod_id ) t6 left join ( select portfolio_id, finprod_id,sec_acct_id, nvl(sum(case when hoding_type = '01' then AMOUNT end),0) PTL_FLOW_AMOUNT01, nvl(sum(case when hoding_type = '10' then AMOUNT end),0) PTL_FLOW_AMOUNT10 from PTL_SEC_POSITION_FLOW
where 1=1
and portfolio_id in (
#{prot,jdbcType=VARCHAR} )
and finprod_id = #{finprodId,jdbcType=VARCHAR}
and cdate <= to_date(#{cdate},'yyyy-MM-dd')
#{secFlowHodingType,jdbcType=VARCHAR}
group by portfolio_id,finprod_id,sec_acct_id ) t7 on t7.portfolio_id = t6.portfolio_id and t7.finprod_id = t6.finprod_id and t7.sec_acct_id=t6.sec_acct_id left join ( select A.portfolio_id, A.finprod_id, A.sec_acct_id, nvl(sum(case when A.hoding_type = 'E01' then A.AMOUNT end),0) ETR_FLOW_AMOUNTE01, nvl(sum(case when A.hoding_type = '04' then A.AMOUNT end),0) ETR_FLOW_AMOUNT04 from ( select A.portfolio_id, A.sec_acct_id, A.finprod_id, A.AMOUNT, A.hoding_type from ETR_SEC_POSITION A
where 1=1
and A.portfolio_id in (
#{prot,jdbcType=VARCHAR} )
and A.cdate = to_date(#{cdate},'yyyy-MM-dd')
and finprod_id = #{finprodId,jdbcType=VARCHAR}
#{etrFlowHodingType,jdbcType=VARCHAR}
)A group by A.portfolio_id, A.finprod_id, A.sec_acct_id ) t8 on t8.portfolio_id = t6.portfolio_id and t8.finprod_id = t6.finprod_id and t8.sec_acct_id = t6.sec_acct_id
left join ( select portfolio_id, finprod_id,sec_acct_id, sum(AMOUNT) andOneDataAmout from PTL_SEC_POSITION_FLOW
where 1=1
and portfolio_id in (
#{prot,jdbcType=VARCHAR} )
and finprod_id = #{finprodId,jdbcType=VARCHAR}
and cdate > to_date(#{cdate},'yyyy-MM-dd') AND AMOUNT < 0 AND HODING_TYPE = '03' AND TRADE_ID IN ( SELECT TOTLE_TRADE_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE FINPROD_TYPE2 = 'F01' AND TRADE_DATE <= to_date(#{cdate},'yyyy-MM-dd') AND SETTLE_DATE > to_date(#{cdate},'yyyy-MM-dd') AND TRADE_STATUS = '01' AND (IS_CANCEL = 'N' OR IS_CANCEL IS NULL) UNION ALL SELECT QUOTE_ID tradeId FROM IBU_QUOTE_BOND WHERE FINPROD_TYPE2 = 'F01' AND QUOTE_DATE <= to_date(#{cdate},'yyyy-MM-dd') AND SETTLE_DATE > to_date(#{cdate},'yyyy-MM-dd') AND TRADE_STATUS = '01' UNION ALL SELECT QUOTE_ID tradeId FROM WFL_IBU_QUOTE_BOND2 WHERE FINPROD_TYPE2 = 'F01' AND QUOTE_DATE <= to_date(#{cdate},'yyyy-MM-dd') AND SETTLE_DATE > to_date(#{cdate},'yyyy-MM-dd') AND (TRADE_STATUS = '01' OR TRADE_STATUS IS NULL) UNION ALL SELECT TRADE_ID tradeId FROM REG_FIN_PRODUCT_DEAL WHERE FINPROD_TYPE2 IN ('F01', 'F02', 'F03') AND TRADE_DATE <= to_date(#{cdate},'yyyy-MM-dd') AND SETTLE_DATE > to_date(#{cdate},'yyyy-MM-dd') AND TRADE_STATUS = '01' UNION ALL SELECT TRADE_ID tradeId FROM REG_FIN_PRODUCT_DEAL WHERE FINPROD_TYPE2 IN ('F01', 'F02', 'F03') AND TRADE_DATE <= to_date(#{cdate},'yyyy-MM-dd') AND SETTLE_DATE > to_date(#{cdate},'yyyy-MM-dd') AND TRADE_STATUS = '01' UNION ALL SELECT QUOTE_ID tradeId FROM IBU_QUOTE_CREP WHERE QUOTE_DATE <= to_date(#{cdate},'yyyy-MM-dd') AND TRADE_STATUS = '01' AND (CASE WHEN REPO_PS = 'T07' THEN M_SETTLE_DATE ELSE V_SETTLE_DATE END ) > to_date(#{cdate},'yyyy-MM-dd') UNION ALL SELECT QUOTE_ID tradeId FROM WFL_IBU_QUOTE_CREP WHERE QUOTE_DATE <= to_date(#{cdate},'yyyy-MM-dd') AND TRADE_STATUS = '01' AND (CASE WHEN REPO_PS = 'T07' THEN M_SETTLE_DATE ELSE V_SETTLE_DATE END ) > to_date(#{cdate},'yyyy-MM-dd')
) group by portfolio_id,finprod_id,sec_acct_id ) t_andOneData on t_andOneData.portfolio_id = t6.portfolio_id and t_andOneData.finprod_id = t6.finprod_id and t_andOneData.sec_acct_id = t6.sec_acct_id
) t left join PTL_PORTFOLIO pp on t.PORTFOLIO_ID = pp.PORTFOLIO_ID left join STL_SEC_ACCT_INFO t4 on t4.sec_acct_id = t.sec_acct_id left join FIN_PRODUCT chl on t.SEC_ACCT_ID = chl.FINPROD_ID left join FIN_PRODUCT fp on t.FINPROD_ID = fp.FINPROD_ID left JOIN fin_product_type t5 on t5.finprod_id = t.finprod_id left join (select distinct FINPROD_ID, CHL_FINPROD_ID from FIN_CASH_INFO fci where CHL_FINPROD_ID is not null
and fci.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
) fci on fci.FINPROD_ID = t.FINPROD_ID left join fin_product chl1 on fci.CHL_FINPROD_ID = chl1.FINPROD_ID
left join ( select distinct finprodId, marketPrice from
( SELECT finprodId,marketPrice,valueDate,row_number() over(partition by finprodId ORDER BY valueDate DESC)num FROM ( SELECT fp.FINPROD_ID finprodId, CASE WHEN fpt.TYPE_8 = 'F01' THEN mbvi.PRICE WHEN fpt.TYPE_8 = 'F02' and fp.TRADE_MARKET = '09' THEN frv.VALUATION WHEN fpt.TYPE_8 = 'F02' and fp.TRADE_MARKET in ('03','04') THEN mfmi.CLOSE_PRICE WHEN fpt.TYPE_8 = 'F04' THEN frv.VALUATION WHEN fpt.TYPE_8 = 'F11' THEN msp.CLOSE_PRICE END AS marketPrice, CASE WHEN fpt.TYPE_8 = 'F01' THEN mbvi.VALUE_DATE WHEN fpt.TYPE_8 = 'F02' and fp.TRADE_MARKET = '09' THEN frv.VAL_DATE WHEN fpt.TYPE_8 = 'F02' and fp.TRADE_MARKET in ('03','04') THEN mfmi.VALUE_DATE WHEN fpt.TYPE_8 = 'F04' THEN frv.VAL_DATE WHEN fpt.TYPE_8 = 'F11' THEN msp.DEAL_DATE END AS valueDate FROM FIN_PRODUCT fp INNER JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_DATE <= to_date(#{cdate},'yyyy-MM-dd') LEFT JOIN FIN_PRODUCT_VALUATION frv ON frv.FINPROD_ID = fp.FINPROD_MARKET_ID AND frv.VAL_DATE <= to_date(#{cdate},'yyyy-MM-dd') LEFT JOIN MST_FUND_MARKET_INFO mfmi ON mfmi.FUND_CODE = fp.FINPROD_MARKET_ID AND mfmi.VALUE_DATE <= to_date(#{cdate},'yyyy-MM-dd') LEFT JOIN MST_SHARE_PRICE msp ON msp.SHARES_ID = fp.FINPROD_MARKET_ID AND msp.DEAL_DATE <= to_date(#{cdate},'yyyy-MM-dd') )gavInfo ) WHERE num = 1
) mv on t.FINPROD_ID = mv.finprodId
and t5.type_8 = #{type8,jdbcType=VARCHAR}
and t5.type_9 = #{type9,jdbcType=VARCHAR}
and t5.type_10 = #{type10,jdbcType=VARCHAR}
and t5.type_11 = #{type11,jdbcType=VARCHAR}
and t5.type_12 = #{type12,jdbcType=VARCHAR}
and t.SEC_ACCT_ID in (
#{secManageAcctId,jdbcType=VARCHAR} )
and t5.type_8 is not null
group by t.PORTFOLIO_ID, pp.PORTFOLIO_NAME, NVL(NVL(chl.FINPROD_MARKET_ID, chl1.FINPROD_MARKET_ID), t.SEC_ACCT_ID ), t4.SEC_ACCT_NAME, chl.FINPROD_ABBR, chl1.FINPROD_ABBR, t.FINPROD_ID, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, t5.TYPE_9, t5.TYPE_10, t5.TYPE_11, t5.TYPE_12, t5.TYPE_8, t5.TYPE_7, T5.TYPE_6, mv.marketPrice, fp.trade_market
) mm ) yy
UNION ALL SELECT portfolioId, portfolioName, null as secAcctId, null as secAcctName, null as finprodId, null as finprodMarketId, null as finprodAbbr, null as type9, null as type10, null as type11, null as type12, #{finprodType2_F20} as type8, null as type7, null as type6, SUM(cashBalance) AS actualPositionAmount, SUM(tradeCash) AS tradePositionAmount, SUM(cashAvailable) AS instructionsAmount, null AS pledgeAmount, 0 AS preReductionAmount, SUM(cashBalance) AS marketValue FROM ( select portfolioId, portfolioName, cdate, cashBalance, tradeCash, cashAvailable, (CASH_AMOUNT03 - tradeCash) AS preReductionCash from ( select portfolioId, portfolioName, cdate, /**CASH_AMOUNT03 as cashBalance,现金余额**/ CASH_AMOUNT03 as CASH_AMOUNT03, (case when CASH_FLOW_AMOUNT99 is not null then CASH_AMOUNT03 + CASH_FLOW_AMOUNT99 else CASH_AMOUNT03 end) as cashBalance, /**(CASH_FLOW_AMOUNT01 + CASH_AMOUNT03 + CASH_AMOUNT08) as tradeCash,交易可用**/ (case when CASH_FLOW_AMOUNT99 is not null then CASH_FLOW_AMOUNT01 + CASH_AMOUNT03 + CASH_AMOUNT08 + CASH_FLOW_AMOUNT99 else CASH_FLOW_AMOUNT01 + CASH_AMOUNT03 + CASH_AMOUNT08 end) as tradeCash,/**交易可用需要去掉 CASH_AMOUNT07 add by hh 20201218**/ /**(ETR_AMOUNTE01 + ETR_AMOUNTE02) as cashAvailable,指令可用**/ (case when CASH_FLOW_AMOUNT99 is not null then ETR_AMOUNTE01 + ETR_AMOUNTE02 + CASH_FLOW_AMOUNT99 else ETR_AMOUNTE01 + ETR_AMOUNTE02 end) as cashAvailable from ( select portfolioId, portfolioName, cdate, nvl(CASH_AMOUNT03,0) as CASH_AMOUNT03,/**现金余额 实际 **/ nvl(CASH_AMOUNT07,0) as CASH_AMOUNT07,/**不可取（交易所）**/ nvl(CASH_AMOUNT08,0) as CASH_AMOUNT08,/**预占用**/ nvl(CASH_FLOW_AMOUNT01,0) as CASH_FLOW_AMOUNT01,/**可用**/ nvl(CASH_FLOW_AMOUNT99,0) as CASH_FLOW_AMOUNT99,/**手工调整**/ nvl(ETR_AMOUNTE01,0) as ETR_AMOUNTE01,/**委托指令可用**/ nvl(ETR_AMOUNTE02,0) as ETR_AMOUNTE02 /**委托指令预增**/ from ( select t.portfolio_id as portfolioId, t.portfolio_name as portfolioName, t2.acct_no as acctNo, t2.acct_name as acctName, t2.ccy as ccy, t1.acct_type as acctType, /** to_date('2019-10-16','yyyy-MM-dd') as cdate **/ to_date(#{cdate},'yyyy-MM-dd') as cdate from PTL_PORTFOLIO t INNER JOIN PTL_CAPACCT_INFO t1 on t1.portfolio_id = t.portfolio_id INNER JOIN STL_CAPACCT_INFO t2 on t2.acct_no = t1.acct_no where 1=1
and t.portfolio_id in (
#{prot,jdbcType=VARCHAR} )
and t2.acct_no in (
#{acctNo,jdbcType=VARCHAR} )
group by t.portfolio_id, t.portfolio_name, t2.acct_no, t2.acct_name, t2.ccy, t1.acct_type ) t left join ( select portfolio_id, acct_id, ccy, nvl(sum(case when hoding_type = '03' then AMOUNT end),0) CASH_AMOUNT03, /**现金余额**/ nvl(sum(case when hoding_type = '07' then AMOUNT end),0) CASH_AMOUNT07,/**不可取（交易所）**/ nvl(sum(case when hoding_type = '08' then AMOUNT end),0) CASH_AMOUNT08 /**预占用**/ from PTL_CASH_POSITION where cdate = to_date(#{cdate},'yyyy-MM-dd') /**and hoding_type in ('03')**/
#{ptlHodingType,jdbcType=VARCHAR}
group by portfolio_id, acct_id, ccy ) t3 on t3.portfolio_id = t.portfolioId and t3.acct_id = t.acctNo and t3.ccy = t.ccy left join ( select portfolio_id, acct_id, ccy, nvl(sum(case when hoding_type = '01' then AMOUNT end),0) CASH_FLOW_AMOUNT01,/**可用**/ nvl(sum(case when hoding_type = '99' and cdate = to_date(#{cdate},'yyyy-MM-dd') then AMOUNT end),0) CASH_FLOW_AMOUNT99 /**手工调整**/ from PTL_CASH_POSITION_FLOW where cdate <= to_date(#{cdate},'yyyy-MM-dd') /**and cdate = to_date('2019-10-16','yyyy-MM-dd') **/ /**and hoding_type in ('01','03','07','08','99') **/
#{ptlFlowHodingType,jdbcType=VARCHAR}
group by portfolio_id, acct_id, ccy ) t4 on t4.portfolio_id = t.portfolioId and t4.acct_id = t.acctNo and t4.ccy = t.ccy left join ( /** njl 20200726 update 拆借拆入指令生效后应该不增加指令可用头寸、预增现金start**/ select aa.portfolio_id, aa.acct_id, aa.ccy, nvl(sum(case when aa.hoding_type = 'E01' then aa.AMOUNT end), 0) ETR_AMOUNTE01, /**委托指令可用**/ nvl(sum(case when bb.busi_ps='01' then 0 when aa.hoding_type = 'E02' then aa.AMOUNT end), 0) ETR_AMOUNTE02 /**委托指令预增**/ from ETR_CASH_POSITION aa left join ( select distinct t.portfolio_id, t.entrust_date, t1.busi_ps from etr_entrust t, etr_entrust_add t1 where t.entrust_id = t1.entrust_id
and t.portfolio_id in (
#{prot,jdbcType=VARCHAR} )
and t1.busi_ps = '01' and t.entrust_date = to_date(#{cdate},'yyyy-MM-dd') ) bb on aa.cdate = bb.entrust_date and aa.portfolio_id=bb.portfolio_id where cdate = to_date(#{cdate},'yyyy-MM-dd') /**and cdate = to_date('2019-10-16','yyyy-MM-dd') **/ /**and hoding_type in ('E01','E02') **/
#{etrHodingType,jdbcType=VARCHAR}
group by aa.portfolio_id, aa.acct_id, aa.ccy /** njl 20200726 update 拆借拆入指令生效后应该不增加指令可用头寸、预增现金end**/ ) t5 on t5.portfolio_id = t.portfolioId and t5.acct_id = t.acctNo and t5.ccy = t.ccy LEFT JOIN CASH_ART_DEAL t6 ON t6.PORTFOLIO_ID=t.portfolioId AND t6.ACCT_ID=t.acctNo AND t6.ccy = t.ccy AND t6.ADJ_DATE=to_date(#{cdate},'yyyy-MM-dd') ) z ) zz ) nn GROUP BY portfolioId,portfolioName
) tt where ( actualPositionAmount <> 0 or tradePositionAmount <> 0 or instructionsAmount <> 0 or pledgeAmount <> 0 or preReductionAmount <> 0 )
and type8 = #{type8,jdbcType=VARCHAR}
order by portfolioId desc,type8 desc,secAcctId desc,finprodMarketId desc)abc
and abc.finprodId = #{finprodId,jdbcType=VARCHAR}

SELECT
t.finprod_id object,
t.finprod_market_id id,
NVL(t.finprod_abbr,t.finprod_market_id) text
FROM
FIN_PRODUCT t
INNER JOIN fin_product_type t1 on t1.finprod_id = t.finprod_id
WHERE
1=1

    and t1.type_8 = #{type8,jdbcType = VARCHAR}


    and t1.type_9 = #{type9,jdbcType=VARCHAR}


    and t1.type_10 = #{type10,jdbcType=VARCHAR}


    and t1.type_11 = #{type11,jdbcType=VARCHAR}


    and t1.type_12 = #{type12,jdbcType=VARCHAR}


    AND (t.finprod_market_id LIKE CONCAT('%',CONCAT(#{search},'%'))
    OR t.finprod_abbr LIKE CONCAT('%',CONCAT(#{search},'%')))



        #{noshowType8,jdbcType=VARCHAR}

SELECT NVL(SUM(CASE WHEN A.hoding_type = 'E01' THEN A.AMOUNT END),0) ETR_FLOW_AMOUNTE01 FROM ( SELECT A.portfolio_id, A.sec_acct_id, A.finprod_id, A.AMOUNT, A.hoding_type FROM ETR_SEC_POSITION A
where 1=1
and A.portfolio_id in (
#{prot,jdbcType=VARCHAR} )
AND A.cdate = to_date(#{cdate},'yyyy-MM-dd')
AND A.finprod_id = #{finprodId,jdbcType=VARCHAR}
#{etrFlowHodingType,jdbcType=VARCHAR}
)A

        SELECT
			 NVL(SUM(CASE WHEN hoding_type = '03' THEN AMOUNT end),0)+
			 NVL(SUM(CASE WHEN hoding_type = '05' THEN AMOUNT end),0) -
			 NVL(SUM(CASE WHEN hoding_type = '06' THEN AMOUNT end),0)  actualPositionAmount
		FROM PTL_SEC_POSITION

			where 1=1



						and portfolio_id in (

					#{prot,jdbcType=VARCHAR}
				)


			AND CDATE = to_date(#{cdate},'yyyy-MM-dd')

				and finprod_id = #{finprodId,jdbcType=VARCHAR}



					#{secHodingType,jdbcType=VARCHAR}
